INSERT INTO _s495_testaments_xii_m VALUES
('testaments-xii-2-the-eye-desire-and-the-pit',2,4,'canon','genesis',3,6,1,$n$Genesis 3:6 — *it was pleasant to the eyes.* Desire came into the garden through the eye long before Reuben made his list.$n$),
('testaments-xii-2-the-eye-desire-and-the-pit',2,4,'canon','job',31,1,2,$n$Job 31:1 — *I made a covenant with mine eyes.* The remedy for a wandering eye is a covenant, not a theory.$n$),
('testaments-xii-2-the-eye-desire-and-the-pit',2,9,'canon','proverbs',7,22,3,$n$Proverbs 7:22 — *as an ox goeth to the slaughter.* The young man is led away without seeing where the road ends.$n$),
('testaments-xii-7-reuben-in-a-coffin-until-carried-up',7,2,'canon','genesis',50,26,1,$n$Genesis 50:26 — *he was put in a coffin in Egypt.* Joseph's coffin is the pattern the other sons followed.$n$),
('testaments-xii-7-reuben-in-a-coffin-until-carried-up',7,2,'canon','genesis',50,13,2,$n$Genesis 50:13 — *buried him in the cave of the field of Machpelah.* The cave where Jacob lies is the one the Testament has in view.$n$),
('testaments-xii-8-simeon-sits-up-to-speak',8,2,'canon','genesis',48,2,1,$n$Genesis 48:2 — *Yashar'el (Israel) strengthened himself, and sat upon the bed.* A father rising from his sickbed to speak to his sons.$n$),
('testaments-xii-8-simeon-sits-up-to-speak',8,1,'canon','genesis',50,26,2,$n$Genesis 50:26 — *So Joseph died, being an hundred and ten years old.* The Testament dates Simeon's last words by this death.$n$),
('testaments-xii-16-in-egypt-until-the-hand-of-moses',16,2,'canon','psalms',77,20,1,$n$Psalm 77:20 — *by the hand of Moses and Aaron.* The exodus remembered as a flock led out by Moses.$n$),
('testaments-xii-16-in-egypt-until-the-hand-of-moses',16,2,'canon','exodus',12,41,2,$n$Exodus 12:41 — *all the hosts of Yahuah (LORD) went out from the land of Egypt.* The day the waiting in Egypt ended.$n$),
('testaments-xii-17-levi-calls-his-sons-before-he-dies',17,1,'canon','genesis',49,1,1,$n$Genesis 49:1 — *that I may tell you that which shall befall you in the last days.* Jacob called his sons together to say what would befall them.$n$),
('testaments-xii-17-levi-calls-his-sons-before-he-dies',17,2,'canon','2-peter',1,14,2,$n$2 Peter 1:14 — *shortly I must put off this my tabernacle.* One who knew the hour was near and spoke while he could.$n$),
('testaments-xii-23-folly-in-israel-and-jacobs-answer',23,3,'canon','genesis',34,7,1,$n$Genesis 34:7 — *he had wrought folly in Yashar'el (Israel).* The same words the brothers used when they heard.$n$),
('testaments-xii-23-folly-in-israel-and-jacobs-answer',23,2,'canon','genesis',34,30,2,$n$Genesis 34:30 — *Ye have troubled me to make me to stink among the inhabitants of the land.* Jacob's answer to the brothers' deed, kept in scripture beside Levi's account.$n$),
('testaments-xii-23-folly-in-israel-and-jacobs-answer',23,1,'canon','genesis',35,12,3,$n$Genesis 35:12 — *to thy seed after thee will I give the land.* The promise Levi tells his father he is trusting.$n$),
('testaments-xii-27-the-sons-of-levi-and-jochebed-born-in-egypt',27,8,'canon','numbers',26,59,1,$n$Numbers 26:59 — *whom her mother bare to Levi in Egypt.* The birth of the woman who would be the mother of Moses and Aaron.$n$),
('testaments-xii-27-the-sons-of-levi-and-jochebed-born-in-egypt',27,2,'canon','exodus',2,22,2,$n$Exodus 2:22 — *I have been a stranger in a strange land.* The reason given for naming a son from the house of Levi.$n$),
('testaments-xii-27-the-sons-of-levi-and-jochebed-born-in-egypt',27,5,'canon','numbers',3,31,3,$n$Numbers 3:31 — *their charge shall be the ark, and the table, and the candlestick.* What Kohath's house was lifted up to carry.$n$),
('testaments-xii-28-levis-household-and-the-fourth-generation',28,2,'canon','exodus',6,18,1,$n$Exodus 6:18 — *the sons of Kohath; Amram, and Izhar, and Hebron, and Uzziel.* The same four sons of Kohath in the canon's spelling.$n$),
('testaments-xii-28-levis-household-and-the-fourth-generation',28,4,'canon','exodus',6,20,2,$n$Exodus 6:20 — *And Amram took him Jochebed his father’s sister to wife; and she bare him Aaron and Moses.* The marriage inside Levi's house that gave Yashar'el (Israel) Aaron and Moses.$n$),
('testaments-xii-28-levis-household-and-the-fourth-generation',28,6,'canon','genesis',15,16,3,$n$Genesis 15:16 — *in the fourth generation they shall come hither again.* The promise that Levi's careful counting is waiting on.$n$),
('testaments-xii-31-laid-waste-yet-remembered-for-the-fathers',31,1,'canon','ezekiel',5,11,1,$n$Ezekiel 5:11 — *thou hast defiled my sanctuary with all thy detestable things.* The cause of the laying waste.$n$),
('testaments-xii-31-laid-waste-yet-remembered-for-the-fathers',31,2,'canon','deuteronomy',28,37,2,$n$Deuteronomy 28:37 — *an astonishment, a proverb, and a byword, among all nations.* The shame of the scattering, foretold.$n$),
('testaments-xii-31-laid-waste-yet-remembered-for-the-fathers',31,4,'canon','leviticus',26,42,3,$n$Leviticus 26:42 — *Then will I remember my covenant with Jacob, and also my covenant with Isaac.* The fathers' covenant remembered in exile.$n$),
('testaments-xii-31-laid-waste-yet-remembered-for-the-fathers',31,4,'canon','isaiah',1,9,4,$n$Isaiah 1:9 — *Except Yahuah Tseva'ot (LORD of hosts) had left unto us a very small remnant.* Only mercy leaves a remnant.$n$),
('testaments-xii-33-seventy-weeks-and-the-priesthood-of-levi',33,1,'canon','daniel',9,24,1,$n$Daniel 9:24 — *Seventy weeks are determined upon thy people and upon thy holy city.* The seventy weeks Levi has in mind.$n$),
('testaments-xii-33-seventy-weeks-and-the-priesthood-of-levi',33,2,'canon','malachi',2,6,2,$n$Malachi 2:6 — *The law of truth was in his mouth.* The priest as Malachi remembers him.$n$),
('testaments-xii-33-seventy-weeks-and-the-priesthood-of-levi',33,10,'canon','ezra',1,5,3,$n$Ezra 1:5 — *to go up to build the house of Yahuah (LORD) which is in Jerusalem.* The return that renewed the house.$n$),
('testaments-xii-33-seventy-weeks-and-the-priesthood-of-levi',33,11,'canon','malachi',2,8,4,$n$Malachi 2:8 — *ye have corrupted the covenant of Levi.* The priesthood corrupted by its own priests.$n$),
('testaments-xii-37-strength-against-the-lion-and-the-bear',37,1,'canon','psalms',44,3,1,$n$Psalm 44:3 — *because thou hadst a favour unto them.* Where the strength of the field really comes from.$n$),
('testaments-xii-37-strength-against-the-lion-and-the-bear',37,4,'canon','1-samuel',17,37,2,$n$1 Samuel 17:37 — *Yahuah (LORD) that delivered me out of the paw of the lion, and out of the paw of the bear.* David names who delivered him.$n$),
('testaments-xii-37-strength-against-the-lion-and-the-bear',37,4,'canon','genesis',49,9,3,$n$Genesis 49:9 — *Yahudah (Judah) is a lion’s whelp.* Jacob's word over the son of the lion.$n$),
('testaments-xii-38-the-giant-kings-and-the-angel-that-followed-judah',38,3,'jasher','jasher',37,32,1,$n$Jasher 37:32 — *Judah took up a large stone from the ground, and its weight was sixty shekels.* The same stone the Testament weighs at sixty.$n$),
('testaments-xii-38-the-giant-kings-and-the-angel-that-followed-judah',38,7,'canon','deuteronomy',3,11,2,$n$Deuteronomy 3:11 — *only Og king of Bashan remained of the remnant of giants.* The measure of the giants the Torah remembers.$n$),
('testaments-xii-38-the-giant-kings-and-the-angel-that-followed-judah',38,10,'canon','genesis',48,16,3,$n$Genesis 48:16 — *The Angel which redeemed me from all evil.* The Angel who followed Jacob and his house.$n$),
('testaments-xii-39-a-thousand-chased-and-hazor-taken',39,1,'canon','joshua',23,10,1,$n$Joshua 23:10 — *One man of you shall chase a thousand.* The promise behind a thousand put to flight.$n$),
('testaments-xii-39-a-thousand-chased-and-hazor-taken',39,2,'jasher','jasher',38,14,2,$n$Jasher 38:14 — *Judah sprang upon the top of the wall.* The same leap over a wall, remembered in Jasher.$n$),
('testaments-xii-39-a-thousand-chased-and-hazor-taken',39,3,'canon','joshua',11,10,3,$n$Joshua 11:10 — *Hazor beforetime was the head of all those kingdoms.* The greatest of the Canaanite cities.$n$),
('testaments-xii-40-drawn-down-from-the-wall-and-the-tower-burned',40,3,'canon','joshua',8,5,1,$n$Joshua 8:5 — *when they come out against us, as at the first, that we will flee before them.* The plan of drawing the city out.$n$),
('testaments-xii-40-drawn-down-from-the-wall-and-the-tower-burned',40,5,'canon','joshua',8,8,2,$n$Joshua 8:8 — *according to the commandment of Yahuah (LORD) shall ye do.* A burning done at a word.$n$),
('testaments-xii-40-drawn-down-from-the-wall-and-the-tower-burned',40,2,'jasher','jasher',38,30,3,$n$Jasher 38:30 — *Judah went up first to the east part of the city.* Judah first on the east side of a walled city.$n$),
('testaments-xii-40-drawn-down-from-the-wall-and-the-tower-burned',40,6,'jasher','jasher',39,2,4,$n$Jasher 39:2 — *they thought to retake from them the booty and the spoil.* The men of the city coming out to retake the spoil.$n$),
('testaments-xii-41-women-on-the-wall-and-the-waters-of-kozeba',41,1,'canon','genesis',38,5,1,$n$Genesis 38:5 — *he was at Chezib, when she bare him.* The place the Testament writes as Kozeba.$n$),
('testaments-xii-41-women-on-the-wall-and-the-waters-of-kozeba',41,4,'canon','2-samuel',11,21,2,$n$2 Samuel 11:21 — *did not a woman cast a piece of a millstone upon him from the wall.* What a stone from the wall can do.$n$),
('testaments-xii-41-women-on-the-wall-and-the-waters-of-kozeba',41,4,'jasher','jasher',39,9,3,$n$Jasher 39:9 — *all their women were engaged in slinging against the sons of Jacob.* Women defending a city by slinging from above.$n$),
('testaments-xii-42-the-gates-opened-by-night-and-thamna-built',42,2,'canon','joshua',9,4,1,$n$Joshua 9:4 — *They did work wilily, and went and made as if they had been ambassadors.* A stratagem seen from the other side.$n$),
('testaments-xii-42-the-gates-opened-by-night-and-thamna-built',42,9,'jubilees','jubilees',34,8,2,$n$Jubilees 34:8 — *and he built Rôbêl and Tamnâtârês* The same two places the Testament names as built after the war.$n$),
('testaments-xii-42-the-gates-opened-by-night-and-thamna-built',42,11,'canon','genesis',35,5,3,$n$Genesis 35:5 — *the terror of Elohim (God) was upon the cities that were round about them.* Why the cities left them alone.$n$),
('testaments-xii-42-the-gates-opened-by-night-and-thamna-built',42,1,'jasher','jasher',39,14,4,$n$Jasher 39:14 — *the people of Gaash had gathered against them to battle.* Gaash gathering against the sons of Jacob.$n$),
('testaments-xii-43-the-adullamite-and-the-daughter-of-shua',43,2,'canon','genesis',38,2,1,$n$Genesis 38:2 — *Yahudah (Judah) saw there a daughter of a certain Canaanite, whose name was Shuah.* How Genesis tells the marriage.$n$),
('testaments-xii-43-the-adullamite-and-the-daughter-of-shua',43,2,'canon','genesis',28,1,2,$n$Genesis 28:1 — *Thou shalt not take a wife of the daughters of Canaan.* The charge the house of Jacob had been given.$n$),
('testaments-xii-43-the-adullamite-and-the-daughter-of-shua',43,3,'canon','1-chronicles',2,3,3,$n$1 Chronicles 2:3 — *which three were born unto him of the daughter of Shua the Canaanitess.* The three sons of Yahudah's (Judah's) first marriage.$n$),
('testaments-xii-44-esau-and-the-arrow-the-iron-city-and-the-tribute',44,1,'canon','genesis',35,29,1,$n$Genesis 35:29 — *his sons Esau and Jacob buried him.* The brothers at their father's burial.$n$),
('testaments-xii-44-esau-and-the-arrow-the-iron-city-and-the-tribute',44,3,'jubilees','jubilees',38,2,2,$n$Jubilees 38:2 — *Jacob bent his bow and sent forth the arrow and struck Esau, his brother.* The arrow that struck Esau, as Jubilees tells it.$n$),
('testaments-xii-44-esau-and-the-arrow-the-iron-city-and-the-tribute',44,7,'jubilees','jubilees',38,12,3,$n$Jubilees 38:12 — *they paid tribute to Jacob and to his sons always.* Peace made, and tribute paid.$n$),
('testaments-xii-62-hired-for-the-mandrakes-the-naming-of-issachar',62,15,'canon','genesis',30,18,1,$n$Genesis 30:18 — *Elohim (God) hath given me my hire … and she called his name Issachar.* The name Issachar is tied to the hire Leah paid, and the Testament of Issachar says the same.$n$),
('testaments-xii-62-hired-for-the-mandrakes-the-naming-of-issachar',62,3,'canon','genesis',30,14,2,$n$Genesis 30:14 — *Rachel said to Leah, Give me, I pray thee, of thy son’s mandrakes.* Reuben brings the mandrakes home and the sisters' quarrel begins, in Genesis as in the Testament of Issachar.$n$),
('testaments-xii-62-hired-for-the-mandrakes-the-naming-of-issachar',62,14,'canon','genesis',30,16,3,$n$Genesis 30:16 — *I have hired thee with my son’s mandrakes.* Jacob's night with Leah is bargained for with mandrakes, just as the Testament of Issachar says.$n$),
('testaments-xii-62-hired-for-the-mandrakes-the-naming-of-issachar',62,12,'canon','genesis',29,25,4,$n$Genesis 29:25 — *wherefore then hast thou beguiled me.* Laban's deception, the root of the sisters' rivalry, is what the Testament of Issachar calls craft.$n$),
('testaments-xii-63-yahuah-hearkened-to-rachel-and-she-bare-two',63,4,'canon','genesis',30,22,1,$n$Genesis 30:22 — *And Elohim (God) remembered Rachel, and Elohim (God) hearkened to her, and opened her womb.* Rachel is heard and her womb is opened, in Genesis and in the Testament of Issachar.$n$),
('testaments-xii-63-yahuah-hearkened-to-rachel-and-she-bare-two',63,3,'canon','genesis',30,23,2,$n$Genesis 30:23 — *Elohim (God) hath taken away my reproach.* What Rachel longed for was a son and an end to her reproach, as the Testament of Issachar says.$n$),
('testaments-xii-63-yahuah-hearkened-to-rachel-and-she-bare-two',63,1,'canon','genesis',30,24,3,$n$Genesis 30:24 — *Yahuah (LORD) shall add to me another son.* Rachel asks Yahuah (the LORD) for one more son, which the Testament of Issachar reads as two children in all.$n$),
('testaments-xii-63-yahuah-hearkened-to-rachel-and-she-bare-two',63,5,'canon','genesis',14,18,4,$n$Genesis 14:18 — *priest of the El Elyon (most high God).* Genesis names a priest of the El Elyon (most high God) in the patriarchs' own time; the mandrake offering is the Testament's alone.$n$),
('testaments-xii-81-anger-troubleth-the-soul-and-giveth-place-to-the-devil',81,1,'canon','proverbs',14,29,1,$n$Proverbs 14:29 — *he that is hasty of spirit exalteth folly.* Quickness to wrath is folly, as the Testament of Dan says of the angry soul.$n$),
('testaments-xii-81-anger-troubleth-the-soul-and-giveth-place-to-the-devil',81,3,'canon','james',1,20,2,$n$James 1:20 — *the wrath of man worketh not the righteousness of Elohim (God).* Anger persuades the angry man that he is right, but it never makes him so.$n$),
('testaments-xii-81-anger-troubleth-the-soul-and-giveth-place-to-the-devil',81,5,'canon','proverbs',29,22,3,$n$Proverbs 29:22 — *a furious man aboundeth in transgression.* Anger feeds on itself and abounds in transgression, as the Testament of Dan teaches.$n$),
('testaments-xii-81-anger-troubleth-the-soul-and-giveth-place-to-the-devil',81,6,'canon','ephesians',4,27,4,$n$Ephesians 4:27 — *Neither give place to the devil.* Anger is a door that must not be left open, a warning the Testament of Dan also gives.$n$),
('testaments-xii-85-dan-forget-their-elohim-and-alienated-from-the-land',85,3,'canon','deuteronomy',32,18,1,$n$Deuteronomy 32:18 — *hast forgotten Elohim (God) that formed thee.* Forgetting Elohim (God) is the old charge in Moses' song, and the Testament of Dan repeats it over his own tribe.$n$),
('testaments-xii-85-dan-forget-their-elohim-and-alienated-from-the-land',85,3,'canon','judges',18,30,2,$n$Judges 18:30 — *the children of Dan set up the graven image.* Dan's turning aside to an image is told in Judges and lies behind the Testament of Dan's foretelling.$n$),
('testaments-xii-85-dan-forget-their-elohim-and-alienated-from-the-land',85,2,'canon','genesis',49,31,3,$n$Genesis 49:31 — *There they buried Abraham and Sarah his wife.* Genesis names the patriarchs' burying place, beside which the Testament of Dan says Dan was laid.$n$),
('testaments-xii-92-i-believe-elohim-that-joseph-liveth',92,2,'canon','genesis',45,28,1,$n$Genesis 45:28 — *Joseph my son is yet alive.* Jacob's faith that Joseph lives, in the Testament of Naphtali, becomes his plain word in Genesis.$n$),
('testaments-xii-92-i-believe-elohim-that-joseph-liveth',92,1,'canon','genesis',37,11,2,$n$Genesis 37:11 — *And his brethren envied him; but his father observed the saying.* Jacob did not forget Joseph's dreams, as Genesis and the Testament of Naphtali both show.$n$),
('testaments-xii-92-i-believe-elohim-that-joseph-liveth',92,3,'canon','genesis',37,35,3,$n$Genesis 37:35 — *but he refused to be comforted; and he said, For I will go down into the grave unto my son mourning.* Jacob's mourning for Joseph, the weeping in the Testament of Naphtali, is the same grief Genesis records.$n$),
('testaments-xii-92-i-believe-elohim-that-joseph-liveth',92,4,'canon','genesis',37,33,4,$n$Genesis 37:33 — *an evil beast hath devoured him.* The brothers' silence let Jacob believe a lie, and the Testament of Naphtali says one of them longed to speak.$n$),
('testaments-xii-61-buried-in-hebron-with-his-fathers',94,1,'canon','genesis',49,29,3,$n$Genesis 49:29 — *bury me with my fathers in the cave that is in the field of Ephron the Hittite* A dying patriarch asks to be buried with his fathers, as Jacob did in Genesis and Naphtali does in his Testament.$n$),
('testaments-xii-61-buried-in-hebron-with-his-fathers',94,1,'canon','genesis',23,19,4,$n$Genesis 23:19 — *the same is Hebron in the land of Canaan.* Abraham buried Sarah at Hebron, the cave to which Naphtali asks to be carried.$n$),
('testaments-xii-61-buried-in-hebron-with-his-fathers',94,2,'canon','genesis',49,33,5,$n$Genesis 49:33 — *and yielded up the ghost, and was gathered unto his people.* Naphtali ends his charge and dies like Jacob, gathered to his people.$n$),
('testaments-xii-61-buried-in-hebron-with-his-fathers',94,3,'canon','genesis',50,12,6,$n$Genesis 50:12 — *his sons did unto him according as he commanded them.* Sons who carry out a dying father's command are the picture in both Genesis and the Testament of Naphtali.$n$),
('testaments-xii-61-buried-in-hebron-with-his-fathers',110,1,'canon','genesis',25,8,7,$n$Genesis 25:8 — *died in a good old age.* Asher's end in the Testament of Asher is told in the words used of Abraham.$n$),
('testaments-xii-61-buried-in-hebron-with-his-fathers',110,1,'canon','genesis',49,31,8,$n$Genesis 49:31 — *There they buried Abraham and Sarah his wife.* Hebron holds the fathers' graves, which is why Asher asks to be carried there.$n$),
('testaments-xii-61-buried-in-hebron-with-his-fathers',110,2,'canon','genesis',50,13,9,$n$Genesis 50:13 — *his sons carried him into the land of Canaan.* Jacob's sons carried him to Machpelah just as Asher's sons carry him to Hebron.$n$),
('testaments-xii-115-woman-reverence-elohim-and-do-not-this-evil-deed',115,2,'canon','genesis',39,9,1,$n$Genesis 39:9 — *how then can I do this great wickedness, and sin against Elohim (God).* Joseph refuses on account of Elohim (God), in Genesis and in the Testament of Joseph alike.$n$),
('testaments-xii-115-woman-reverence-elohim-and-do-not-this-evil-deed',115,1,'canon','exodus',20,14,2,$n$Exodus 20:14 — *Thou shalt not commit adultery.* The commandment against adultery is what the woman asks Joseph to break and what he keeps.$n$),
('testaments-xii-115-woman-reverence-elohim-and-do-not-this-evil-deed',115,1,'canon','proverbs',6,26,3,$n$Proverbs 6:26 — *the adulteress will hunt for the precious life.* Proverbs warns that the adulteress hunts for a man's life, as the woman in the Testament of Joseph does.$n$),
('testaments-xii-115-woman-reverence-elohim-and-do-not-this-evil-deed',115,4,'canon','proverbs',7,21,4,$n$Proverbs 7:21 — *With her much fair speech she caused him to yield.* Gifts and flattery are the adulteress's snares, in the Testament of Joseph and in Proverbs.$n$),
('testaments-xii-117-seizing-an-opportunity-she-rushed-unto-me-and-the-cords-of-sin',117,3,'canon','genesis',39,10,1,$n$Genesis 39:10 — *as she spake to Joseph day by day, that he hearkened not unto her* Day after day she pressed him, and Joseph would not listen, in Genesis and in the Testament of Joseph.$n$),
('testaments-xii-117-seizing-an-opportunity-she-rushed-unto-me-and-the-cords-of-sin',117,7,'canon','genesis',39,8,2,$n$Genesis 39:8 — *my master wotteth not what is with me in the house.* Joseph answers out of faithfulness to his master, which the Testament of Joseph puts as speaking because of his lord.$n$),
('testaments-xii-117-seizing-an-opportunity-she-rushed-unto-me-and-the-cords-of-sin',117,8,'canon','proverbs',5,22,3,$n$Proverbs 5:22 — *he shall be holden with the cords of his sins.* A man bound by his own desire is held by it, as the Testament of Joseph and Proverbs both say.$n$),
('testaments-xii-122-grace-from-heaven-is-upon-him-bought-into-potiphars-house',122,3,'canon','genesis',39,3,1,$n$Genesis 39:3 — *his master saw that Yahuah (LORD) was with him.* What Potiphar saw in Joseph is what the Testament of Joseph has the Egyptian woman say.$n$),
('testaments-xii-122-grace-from-heaven-is-upon-him-bought-into-potiphars-house',122,3,'canon','genesis',39,5,2,$n$Genesis 39:5 — *Yahuah (LORD) blessed the Egyptian’s house for Joseph’s sake.* A house is blessed for Joseph's sake, in Genesis and in the Testament of Joseph.$n$),
('testaments-xii-122-grace-from-heaven-is-upon-him-bought-into-potiphars-house',122,2,'canon','genesis',40,15,3,$n$Genesis 40:15 — *I was stolen away out of the land of the Hebrews.* Joseph was stolen from his own land, as Genesis has him say and the Testament of Joseph has the woman say.$n$),
('testaments-xii-122-grace-from-heaven-is-upon-him-bought-into-potiphars-house',122,1,'canon','genesis',39,1,4,$n$Genesis 39:1 — *Potiphar, an officer of Pharaoh, captain of the guard, an Egyptian, bought him.* Potiphar buys Joseph in Genesis, and the Testament of Joseph tells the buying in more colour.$n$),
('testaments-xii-123-art-thou-a-slave-or-free-and-i-said-a-slave',123,8,'canon','genesis',37,28,1,$n$Genesis 37:28 — *sold Joseph to the Ishmeelites for twenty pieces of silver.* Joseph's sale out of Canaan is the plain fact under his answer to Pentephris.$n$),
('testaments-xii-123-art-thou-a-slave-or-free-and-i-said-a-slave',123,3,'canon','genesis',39,1,2,$n$Genesis 39:1 — *bought him of the hands of the Ishmeelites.* The Ishmeelites are the sellers in both the Testament of Joseph and Genesis.$n$),
('testaments-xii-123-art-thou-a-slave-or-free-and-i-said-a-slave',123,6,'canon','psalms',105,17,3,$n$Psalm 105:17 — *He sent a man before them, even Joseph, who was sold for a servant.* Joseph answers "a slave" and the psalm says he was sold for a servant.$n$),
('testaments-xii-123-art-thou-a-slave-or-free-and-i-said-a-slave',123,9,'canon','psalms',105,18,4,$n$Psalm 105:18 — *Whose feet they hurt with fetters.* Joseph's suffering as a slave is told in Psalm 105 and in the Testament of Joseph.$n$),
('testaments-xii-124-the-captive-well-born-lad-in-bonds-and-the-word-that-tried-him',124,2,'canon','genesis',39,20,1,$n$Genesis 39:20 — *put him into the prison, a place where the king’s prisoners were bound* Joseph is shut in the king's prison, in Genesis and in the Testament of Joseph.$n$),
('testaments-xii-124-the-captive-well-born-lad-in-bonds-and-the-word-that-tried-him',124,4,'canon','genesis',39,7,2,$n$Genesis 39:7 — *his master’s wife cast her eyes upon Joseph.* Her desire for Joseph begins with a look, in Genesis and in the Testament of Joseph.$n$),
('testaments-xii-124-the-captive-well-born-lad-in-bonds-and-the-word-that-tried-him',124,2,'canon','psalms',105,19,3,$n$Psalm 105:19 — *the word of Yahuah (LORD) tried him.* The prison tested Joseph, as the psalm says of this season of his life.$n$),
('testaments-xii-126-i-knew-it-and-held-my-peace-lest-the-eunuch-be-put-to-shame',126,6,'canon','proverbs',12,16,1,$n$Proverbs 12:16 — *A fool’s wrath is presently known: but a prudent man covereth shame.* Joseph's silence about the eunuch's lie is the prudence Proverbs describes.$n$),
('testaments-xii-126-i-knew-it-and-held-my-peace-lest-the-eunuch-be-put-to-shame',126,2,'canon','genesis',37,36,2,$n$Genesis 37:36 — *the Midianites sold him into Egypt unto Potiphar.* Joseph is sold on to Potiphar, as Genesis says, though the Testament of Joseph tells of the buying differently.$n$),
('testaments-xii-126-i-knew-it-and-held-my-peace-lest-the-eunuch-be-put-to-shame',126,5,'canon','genesis',37,28,3,$n$Genesis 37:28 — *sold Joseph to the Ishmeelites for twenty pieces of silver* What Joseph was sold for in Genesis is the price of the first sale; the Testament of Joseph tells of a second.$n$);
CREATE TEMP TABLE _s495_testaments_xii_j (slug TEXT) ON COMMIT DROP;
INSERT INTO _s495_testaments_xii_j VALUES
('testaments-xii-61-buried-in-hebron-with-his-fathers');

CREATE OR REPLACE TEMP VIEW _s495_testaments_xii_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id, v.text
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon', 'enoch', 'jubilees', 'jasher', 'apocrypha', 'apocrypha-charles-vol1', 'pseudepigrapha', 'adam-eve-conflict', 'apocalypse-of-abraham', 'ascension-isaiah', 'sonnini-acts-29', 'josephus', 'lightfoot-apostolic-fathers', 'mrjames-apocryphal-nt');

DO $s495$
DECLARE r RECORD; sid BIGINT; tid BIGINT; ltext TEXT; n INT;
        n_cards INT := 0; n_cards_same INT := 0; n_thr INT := 0; n_thr_same INT := 0; n_mem INT := 0; n_mem_same INT := 0; n_total INT;
BEGIN
  -- ---- guards: every row is checked before anything is written ----
  FOR r IN SELECT * FROM _s495_testaments_xii_c LOOP
    SELECT verse_id, text INTO sid, ltext FROM _s495_testaments_xii_lookup WHERE edition_slug = r.src_edition AND book_slug = r.src_slug AND chapter_number = r.src_ch AND verse_number = r.src_v;
    IF sid IS NULL THEN RAISE EXCEPTION 'S495: source verse %/% %:% missing', r.src_edition, r.src_slug, r.src_ch, r.src_v; END IF;
    IF ltext <> r.src_text THEN RAISE EXCEPTION 'S495: live text of %/% %:% differs from the read-back this migration was written against — re-run the dump and rebuild', r.src_edition, r.src_slug, r.src_ch, r.src_v; END IF;
    SELECT verse_id, text INTO tid, ltext FROM _s495_testaments_xii_lookup WHERE edition_slug = r.tgt_edition AND book_slug = r.tgt_slug AND chapter_number = r.tgt_ch AND verse_number = r.tgt_v;
    IF tid IS NULL THEN RAISE EXCEPTION 'S495: target verse %/% %:% missing', r.tgt_edition, r.tgt_slug, r.tgt_ch, r.tgt_v; END IF;
    -- canon quotations follow the restored-names KJV of parsed/canon.json by convention (the live canon display text is modernised), so only non-canon targets are compared
    IF r.tgt_edition <> 'canon' AND position(ltext IN r.note) = 0 THEN RAISE EXCEPTION 'S495: note for %:% -> %/% %:% does not carry the live target verse verbatim', r.src_ch, r.src_v, r.tgt_edition, r.tgt_slug, r.tgt_ch, r.tgt_v; END IF;
    IF sid = tid THEN RAISE EXCEPTION 'S495: source = target at %:%', r.src_ch, r.src_v; END IF;
  END LOOP;
  FOR r IN SELECT * FROM _s495_testaments_xii_t LOOP
    IF NOT EXISTS (SELECT 1 FROM _s495_testaments_xii_lookup WHERE edition_slug = 'pseudepigrapha' AND book_slug = 'testaments-xii' AND chapter_number = r.ch AND verse_number = r.a_vn)
    OR NOT EXISTS (SELECT 1 FROM _s495_testaments_xii_lookup WHERE edition_slug = 'pseudepigrapha' AND book_slug = 'testaments-xii' AND chapter_number = r.ch AND verse_number = r.z_vn) THEN
      RAISE EXCEPTION 'S495: anchor %:%-% for thread % missing', r.ch, r.a_vn, r.z_vn, r.slug; END IF;
  END LOOP;
  FOR r IN SELECT * FROM _s495_testaments_xii_j LOOP
    IF NOT EXISTS (SELECT 1 FROM cross_reference_threads WHERE slug = r.slug) THEN RAISE EXCEPTION 'S495: thread to join % does not exist', r.slug; END IF;
  END LOOP;

  -- ---- cards ----
  SELECT count(*) INTO n_total FROM _s495_testaments_xii_c;
  WITH input(src_edition, src_slug, src_ch, src_v, tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS
       (SELECT src_edition, src_slug, src_ch, src_v, tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note FROM _s495_testaments_xii_c)
  INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
  SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
    FROM input i
    JOIN _s495_testaments_xii_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
    JOIN _s495_testaments_xii_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
   WHERE sv.verse_id <> tv.verse_id
  ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;
  GET DIAGNOSTICS n_cards = ROW_COUNT; n_cards_same := n_total - n_cards;

  -- ---- threads ----
  SELECT count(*) INTO n_total FROM _s495_testaments_xii_t;
  INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
  SELECT t.slug, t.title, t.summary_md, sv.verse_id, ev.verse_id, t.tier::content_tier, t.sort_order
    FROM _s495_testaments_xii_t t
    JOIN _s495_testaments_xii_lookup sv ON sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=t.ch AND sv.verse_number=t.a_vn
    JOIN _s495_testaments_xii_lookup ev ON ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=t.ch AND ev.verse_number=t.z_vn
  ON CONFLICT (slug) DO NOTHING;
  GET DIAGNOSTICS n_thr = ROW_COUNT; n_thr_same := n_total - n_thr;

  -- ---- members (thread by slug — new or joined; card by its verse pair, source='manual') ----
  SELECT count(*) INTO n_total FROM _s495_testaments_xii_m;
  INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
  SELECT th.id, x.id, m.sort_order, m.member_note
    FROM _s495_testaments_xii_m m
    JOIN cross_reference_threads th ON th.slug = m.thread_slug
    JOIN _s495_testaments_xii_lookup sv ON sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=m.src_ch AND sv.verse_number=m.src_v
    JOIN _s495_testaments_xii_lookup tv ON tv.edition_slug=m.tgt_edition AND tv.book_slug=m.tgt_slug AND tv.chapter_number=m.tgt_ch AND tv.verse_number=m.tgt_v
    JOIN cross_references x ON x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual'
  ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
  GET DIAGNOSTICS n_mem = ROW_COUNT; n_mem_same := n_total - n_mem;
  -- every member row must now exist (a card or thread that failed to resolve would leave one short)
  SELECT count(*) INTO n FROM _s495_testaments_xii_m m WHERE NOT EXISTS (
    SELECT 1 FROM cross_reference_thread_members mm JOIN cross_reference_threads th ON th.id = mm.thread_id AND th.slug = m.thread_slug
      JOIN cross_references x ON x.id = mm.cross_reference_id
      JOIN _s495_testaments_xii_lookup sv ON sv.verse_id = x.source_verse_id AND sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=m.src_ch AND sv.verse_number=m.src_v
      JOIN _s495_testaments_xii_lookup tv ON tv.verse_id = x.target_verse_id AND tv.edition_slug=m.tgt_edition AND tv.book_slug=m.tgt_slug AND tv.chapter_number=m.tgt_ch AND tv.verse_number=m.tgt_v);
  IF n > 0 THEN RAISE EXCEPTION 'S495: % member row(s) did not resolve to a thread + card', n; END IF;

  RAISE NOTICE 'S495 (testaments-xii) summary: cards inserted % / already there %; threads inserted % / already there %; members inserted % / already there %',
    n_cards, n_cards_same, n_thr, n_thr_same, n_mem, n_mem_same;
END $s495$;
COMMIT;
\echo 'session495 — testaments-xii gap fill done.'
